-- "Ultimate Trainer Test": rebuilt from Mark's "Disaster", 4:15 ride from 15 Dec 2018 (Favero Assioma, FTP 263, NP 212, IF 0.81, TSS 276),
-- rebuilt as a structured ERG ride from the power chart. Targets are % of FTP.
--   0:00  Warm-up 27 min building 50 -> 70%, then 3 x 15 s sprints at 150-160% (2:45 easy)
--   0:37  4 x 10 min at 95-100% FTP, 8 min recoveries at 45-50%
--   1:49  46 min steady at 68-73% (reads ~65-70% on the chart)
--   2:41  7 x 2 min at 110-115%, 1:30 recoveries
--   3:12  35 min at 82-88% with a 10 s kick at 150-160% every 3:30 (the spikes in the chart)
--   3:53  17 min steady at 70-75%, 6 min cool-down
-- Planned at FTP 263: NP 211, avg 192 W, IF 0.80, TSS 274, 255 min.
insert into workouts (id, name, steps, source, category, duration_sec) values
  ('prebuilt-ultimate-trainer-test-255', 'Ultimate Trainer Test', '[{"low":50,"high":55,"note":"Warm up - easy","type":"step","duration":600,"targetType":"ftp_pct"},{"low":60,"high":65,"note":"Warm up - steady","type":"step","duration":600,"targetType":"ftp_pct"},{"low":65,"high":70,"note":"Warm up - build","type":"step","duration":420,"targetType":"ftp_pct"},{"type":"repeat","steps":[{"low":150,"high":160,"note":"Sprint - 15 s","type":"step","duration":15,"targetType":"ftp_pct"},{"low":60,"high":65,"note":"Easy spin","type":"step","duration":165,"targetType":"ftp_pct"}],"repetitions":3},{"low":65,"high":70,"note":"Settle in","type":"step","duration":60,"targetType":"ftp_pct"},{"type":"repeat","steps":[{"low":95,"high":100,"note":"Threshold block - 10 min","type":"step","duration":600,"targetType":"ftp_pct"},{"low":45,"high":50,"note":"Recover","type":"step","duration":480,"targetType":"ftp_pct"}],"repetitions":4},{"low":68,"high":73,"note":"Long steady endurance - hold it smooth","type":"step","duration":2760,"targetType":"ftp_pct"},{"low":50,"high":55,"note":"Easy","type":"step","duration":360,"targetType":"ftp_pct"},{"type":"repeat","steps":[{"low":110,"high":115,"note":"Over FTP - 2 min","type":"step","duration":120,"targetType":"ftp_pct"},{"low":50,"high":55,"note":"Recover","type":"step","duration":90,"targetType":"ftp_pct"}],"repetitions":7},{"low":50,"high":55,"note":"Recover","type":"step","duration":330,"targetType":"ftp_pct"},{"type":"repeat","steps":[{"low":82,"high":88,"note":"Sweet spot - settle in","type":"step","duration":200,"targetType":"ftp_pct"},{"low":150,"high":160,"note":"Kick - 10 s","type":"step","duration":10,"targetType":"ftp_pct"}],"repetitions":10},{"low":50,"high":55,"note":"Recover","type":"step","duration":360,"targetType":"ftp_pct"},{"low":70,"high":75,"note":"Final steady block","type":"step","duration":1020,"targetType":"ftp_pct"},{"low":45,"high":50,"note":"Cool down","type":"step","duration":360,"targetType":"ftp_pct"}]'::jsonb, 'prebuilt', 'threshold', 15300)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, category = excluded.category, duration_sec = excluded.duration_sec;
